const MAT8 = {konu:"Çarpanlar, Üslü ve Kareköklü İfadeler, Cebir, Eşitsizlik, Geometri", kaynak:KY("Ortaokul Matematik"),
 p:[["Sayılar ve Nicelikler: Çarpanlar, üslü ve kareköklü ifadeler","Negatif üs, sayının çarpmaya göre tersini verir: 2⁻³ = 1/8. Bilimsel gösterim büyük ve küçük sayıları a × 10ⁿ (1 ≤ a < 10) şeklinde yazar. Tam kare sayıların karekökü tam sayıdır.","√","√49 = 7. √12 = 2√3. 45 000 = 4,5 × 10⁴. 10⁻² = 0,01."],
    ["Cebirsel Düşünme ve Değişimler: Özdeşlikler ve çarpanlara ayırma","Cebirsel ifadeleri çarpar, özdeşlikleri kullanırız: (a + b)² = a² + 2ab + b², (a − b)(a + b) = a² − b².","(a+b)²","(x + 3)² = x² + 6x + 9. x² − 16 = (x − 4)(x + 4)."],
    ["Cebirsel Düşünme: Doğrusal denklemler ve eğim","y = mx + n biçimindeki denklemlerin grafiği doğrudur; m eğimi gösterir. Eğim, dikey değişimin yatay değişime oranıdır.","y=mx","y = 2x + 1 doğrusunda x 1 artınca y 2 artar; eğim 2'dir. x = 0 iken y = 1."],
    ["Cebirsel Düşünme: Eşitsizlikler","Eşitsizliğin iki tarafı negatif bir sayıyla çarpılır veya bölünürse eşitsizlik yön değiştirir. Çözümü sayı doğrusunda gösteririz.","<","2x − 3 > 7 → 2x > 10 → x > 5. −3x < 12 → x > −4 (yön değişti)."],
    ["Geometrik Şekiller: Üçgenler ve Pisagor","Dik üçgende dik kenarların karelerinin toplamı hipotenüsün karesine eşittir: a² + b² = c². Üçgende iki kenar uzunluğunun toplamı üçüncü kenardan büyüktür.","a²+b²","Dik kenarları 6 ve 8 olan üçgenin hipotenüsü √(36 + 64) = √100 = 10'dur."],
    ["Geometrik Nicelikler ve Dönüşüm: Prizmalar, eşlik ve benzerlik","Dik prizmanın hacmi taban alanı × yüksekliktir. Benzer şekillerde karşılık gelen kenarlar orantılıdır. Dönüşümler art arda uygulanabilir.","🧊","Taban alanı 12 cm², yüksekliği 5 cm olan prizmanın hacmi 60 cm³'tür. Silindirin hacmi πr²h."],
    ["İstatistik ve Veriden Olasılığa","Basit olayın olasılığı = istenen durum sayısı / tüm durumların sayısı. Olasılık 0 ile 1 arasındadır.","P(A)","Torbada 3 kırmızı, 5 mavi bilye var. Kırmızı çekme olasılığı 3/8'dir."]],
 q:[["√49 kaçtır?",["6","7","8","9"],1],
    ["(x + 3)² ifadesinin açılımı hangisidir?",["x² + 9","x² + 3x + 9","x² + 6x + 9","x² + 6x + 6"],2],
    ["Dik kenarları 6 ve 8 olan dik üçgenin hipotenüsü kaçtır?",["10","12","14","48"],0],
    ["2x − 3 > 7 eşitsizliğinin çözümü nedir?",["x > 2","x > 5","x < 5","x > 10"],1],
    ["3 kırmızı, 5 mavi bilye olan torbadan kırmızı çekme olasılığı nedir?",["3/5","5/8","3/8","1/3"],2]],
 m:[["Karekök","Karesi verilen sayıyı veren sayı"],["Bilimsel gösterim","a × 10ⁿ biçiminde yazım"],["Özdeşlik","Her değer için doğru olan eşitlik"],["Eğim","Doğrunun dikliğini gösteren oran"],["Hipotenüs","Dik üçgende dik açının karşısındaki kenar"],["Olasılık","İstenen durumun tüm durumlara oranı"]],
 tf:[["2⁻³ = 1/8'dir.",true],["Eşitsizlik negatif sayıyla çarpılınca yön değiştirmez.",false],["Olasılık değeri 1'den büyük olabilir.",false],["Dik üçgende a² + b² = c² bağıntısı vardır.",true]]};

