const DKAB6 = {konu:"Peygamber ve İlahi Kitap İnancı, Ramazan ve Oruç, Ahlaki Davranışlar", kaynak:KAY_DKAB,
 p:[["Peygamber ve ilahi kitap inancı","Peygamberler, Allah'ın insanlara doğru yolu göstermek için seçtiği elçilerdir. Hz. Musa'ya Tevrat, Hz. Davud'a Zebur, Hz. İsa'ya İncil, Hz. Muhammed'e Kur'an verilmiştir.","Kitap"],
    ["Ramazan ve oruç","Oruç, tan yerinin ağarmasından (imsak) akşam ezanına kadar yeme, içme ve orucu bozan davranışlardan uzak durmaktır. Ramazan ayı sabrı, paylaşmayı ve yardımlaşmayı güçlendirir.","Oruç"],
    ["Ahlaki davranışlar","Dürüstlük, sözünde durmak, adalet, hoşgörü ve yardımseverlik güzel ahlaki davranışlardır. Yalan, gıybet ve haksızlık ise ahlaka aykırıdır.","Ahlak"],
    ["Peygamberliğinden önce Hz. Muhammed","Hz. Muhammed yaklaşık 571'de Mekke'de doğdu. Gençliğinde dürüstlüğü ve güvenilirliği nedeniyle 'el-Emîn' (güvenilir kişi) diye anıldı.","el-Emîn"],
    ["Kültürümüzdeki dinî motifler","Hat, tezhip, ebru, cami ve medrese mimarisi gibi sanatlar kültürümüzde dinî duygu ve düşüncenin güzelliğe dönüşmüş hâlidir.","Hat"]],
 q:[["Zebur hangi peygambere verilmiştir?",["Hz. Musa","Hz. Davud","Hz. İsa","Hz. Muhammed"],1],
    ["Hz. Muhammed'in gençliğinde kazandığı 'güvenilir' anlamındaki lakap hangisidir?",["el-Emîn","es-Sıddîk","el-Fârûk","Zünnûreyn"],0],
    ["Oruç hangi vakitler arasında tutulur?",["İmsak ile akşam ezanı arası","Öğle ile ikindi arası","Yatsı ile sabah arası","Yalnızca gece"],0],
    ["Aşağıdakilerden hangisi ilahi kitap değildir?",["Tevrat","İncil","Kur'an","Mesnevi"],3]],
 m:[["İlahi kitap","Allah'ın peygamberlerine gönderdiği kitap"],["İmsak","Orucun başladığı vakit"],["İftar","Orucun akşam açılması"],["Gıybet","Bir kişiyi arkasından, hoşlanmayacağı şekilde anmak"],["Adalet","Herkese hakkını vermek"],["Tezhip","Kitap ve levhaları süsleme sanatı"]],
 tf:[["Hz. Muhammed'e Kur'an indirilmiştir.",true],["Hz. İsa'ya Tevrat verilmiştir.",false],["Ramazan ayı paylaşma ve yardımlaşmayı güçlendirir.",true],["Gıybet güzel bir ahlaki davranıştır.",false]]};

const DKAB7 = {konu:"Melek ve Ahiret İnancı, Hac, Hz. Muhammed ve Dünya Dinleri", kaynak:KAY_DKAB,
 p:[["Melek ve ahiret inancı","Melekler Allah'ın yarattığı, ona itaat eden varlıklardır. Cebrail vahiy getirir; Mikail, İsrafil ve Azrail'in de ayrı görevleri vardır. Ahiret inancı, ölümden sonra sonsuz bir hayatın olduğuna ve herkesin yaptığının karşılığını göreceğine inanmaktır.","Melek"],
    ["Hac, umre ve kurban","Hac, gücü yeten Müslümanlara ömürde bir kez farz olan ve Mekke'de yapılan ibadettir. Umre de Kâbe'yi ziyaret ibadetidir. Kurban, Allah'a yaklaşmak için kesilen hayvanın etinin ihtiyaç sahipleriyle paylaşılmasıdır.","Hac"],
    ["İslam düşüncesinde yorumlar","Müslümanlar dini anlamak için farklı yorumlar geliştirmiştir: itikadi mezhepler, fıkıh mezhepleri ve tasavvufi yorumlar gibi. Yunus Emre, Mevlânâ ve Hacı Bektaş-ı Veli bu zenginliğin temsilcilerindendir. Farklılıklara saygı göstermek önemlidir.","Yorum"],
    ["Peygamber olarak Hz. Muhammed","Hz. Muhammed 40 yaşında Hira Mağarası'nda ilk vahyi aldı. Mekke'de 13 yıl tebliğ etti, 622'de Medine'ye hicret etti. Medine'de yaklaşık 10 yıl yaşadı.","622"],
    ["Yaşayan dünya dinleri","Dünyada Hristiyanlık, Yahudilik, Hinduizm, Budizm gibi birçok din yaşamaktadır. Farklı inançlara saygı göstermek barış içinde yaşamanın gereğidir.","Dinler"]],
 q:[["Vahiy getiren melek hangisidir?",["Cebrail","Mikail","İsrafil","Azrail"],0],
    ["Hac ibadetinin merkezi olan Kâbe hangi şehirdedir?",["Kudüs","Medine","Mekke","Şam"],2],
    ["Hicret hangi şehirden hangi şehre yapılmıştır?",["Medine'den Mekke'ye","Mekke'den Medine'ye","Mekke'den Taif'e","Medine'den Şam'a"],1],
    ["Aşağıdakilerden hangisi tasavvufi düşüncenin temsilcilerindendir?",["Yunus Emre","Aziz Sancar","Piri Reis","Ali Kuşçu"],0]],
 m:[["Melek","Allah'ın yarattığı, ona itaat eden varlık"],["Ahiret","Ölümden sonraki sonsuz hayat"],["Hac","Mekke'de yapılan, gücü yetene farz ibadet"],["Umre","Kâbe'yi ziyaret ibadeti"],["Kurban","Allah'a yaklaşmak için hayvan kesip eti paylaşmak"],["Hicret","Hz. Muhammed'in Mekke'den Medine'ye göçü"]],
 tf:[["Hz. Muhammed Medine'de doğmuştur.",false],["Hicret 622'de gerçekleşmiştir.",true],["Kurban etinin bir kısmı ihtiyaç sahipleriyle paylaşılır.",true],["Farklı yorumlar, Müslümanların dini anlama çabasından doğmuştur.",true]]};

const DKAB8 = {konu:"Kader İnancı, Zekât ve Sadaka, Kur'an ve İnsan, Bilim ve Kültüre Katkı", kaynak:KAY_DKAB,
 p:[["Kader inancı","Kader inancı, Allah'ın ilmiyle her şeyi bildiğine inanmaktır. İnsan irade sahibidir ve seçimlerinden sorumludur. Kader inancı çalışmayı engellemez; üzerine düşeni yapan kişi sonuç karşısında sabır ve tevekkül gösterir.","Kader"],
    ["Zekât ve sadaka","Zekât, belirli miktar mala sahip Müslümanın malının belli bir bölümünü ihtiyaç sahiplerine vermesidir (para ve altında kırkta bir, yani yüzde 2,5). Sadaka karşılıksız yapılan yardımdır; zorunlu değildir, tebessüm bile sadakadır.","Zekât"],
    ["Din ve sosyal hayat","Din, kişinin yanı sıra toplumsal hayatı da etkiler. Yardımlaşma, hoşgörü, komşuluk hakkı ve bayramlardaki dayanışma toplumu güçlendirir.","Toplum"],
    ["Kur'an ve insan","Kur'an insanı düşünmeye, araştırmaya, adaletli olmaya ve iyilik yapmaya çağırır. Mesajları ilim, ahlak ve temel haklar gibi konulara da değinir.","Kur'an"],
    ["Müslümanların bilim ve kültüre katkısı","Harezmî cebirin gelişmesine, İbn-i Sina tıbba (El-Kânûn fi't-Tıb), Biruni astronomi ve coğrafyaya, Cezerî makine bilimine, Ali Kuşçu astronomiye katkı yapmıştır.","Bilim"]],
 q:[["Kader inancına göre insan için hangisi doğrudur?",["İradesi vardır ve seçimlerinden sorumludur","Hiçbir seçim yapamaz","Çalışmanın anlamı yoktur","Sorumluluğu yoktur"],0],
    ["Para ve altında zekât oranı yaklaşık nedir?",["%2,5 (kırkta bir)","%10","%25","%50"],0],
    ["Cebirin gelişmesine öncülük eden bilgin kimdir?",["Harezmî","Biruni","Cezerî","İbn-i Sina"],0],
    ["'El-Kânûn fi't-Tıb' adlı eseri kim yazmıştır?",["İbn-i Sina","Farabi","Biruni","Ali Kuşçu"],0]],
 m:[["Kader","Allah'ın her şeyi önceden bilmesi"],["İrade","Seçme ve karar verme gücü"],["Zekât","Zengin Müslümanın malından verdiği farz miktar"],["Sadaka","Karşılıksız verilen yardım"],["Tevekkül","Üzerine düşeni yapıp sonucu Allah'a bırakmak"],["Hoşgörü","Farklılıklara anlayışla yaklaşmak"]],
 tf:[["Zekât, zengin Müslümanlara farzdır.",true],["Sadaka yalnızca para ile verilir.",false],["Tevekkül, çalışmadan beklemek demektir.",false],["Cezerî makine bilimi alanında önemli çalışmalar yapmıştır.",true]]};

const KUR5 = {konu:"Kur'an-ı Kerim'i Tanıyorum ve Okumaya Giriş", kaynak:KAY_KUR,
 p:[["Kur'an'ı tanıyalım","Kur'an-ı Kerim 114 sureden oluşur. İlk sure Fatiha, en uzun sure Bakara'dır. Kur'an'ı okurken abdestli, temiz ve sakin olmaya özen gösterilir; okumaya Euzü-Besmele ile başlanır.","Kur'an"],
    ["Harfler ve harekeler","Arap alfabesinde 28 harf vardır: ا ب ت ث ج ح خ د ذ ر ز س ش ص ض ط ظ ع غ ف ق ك ل م ن و ه ي. Harekeler harfe ses verir: üstün (بَ) a/e, esre (بِ) i, ötre (بُ) u sesi verir.","بَ"],
    ["Cezm, şedde ve tenvin","Cezm (sükûn) harfin hareke almadan, sessiz okunmasıdır. Şedde, harfin iki kez okunmasını sağlar. Tenvin, üstün, esre veya ötrenin ikişer tane olmasıdır; 'an', 'in', 'un' sesleri verir.","ـّ"],
    ["Med","Med, harfin uzatılarak okunmasıdır. Tabii med bir elif miktarı uzatılır. Medd-i muttasıl ve medd-i munfasıl ise med harfinden sonra hemze gelmesiyle oluşur ve tabii medden daha uzun okunur.","Med"],
    ["Fatiha, İhlas ve Kevser","Fatiha 7, İhlas 4, Kevser 3 ayettir. Fatiha'da Allah'a hamd, Allah'ın merhameti, yalnızca ona kulluk ve doğru yola iletilme duası vardır. Ezber ve okuma için mushaftan ve öğretmeninden kontrol et.","7"]],
 q:[["Arap alfabesinde kaç harf vardır?",["24","28","29","32"],1],
    ["Üstün hareke hangi sesi verir?",["a veya e","i","u","Hiç ses vermez"],0],
    ["Fatiha suresi kaç ayettir?",["4","5","7","10"],2],
    ["Tabii med ne kadar uzatılır?",["Bir elif miktarı","Beş elif miktarı","Hiç uzatılmaz","On elif miktarı"],0]],
 m:[["Hareke","Harfe ses veren işaret"],["Cezm (sükûn)","Harfin sessiz okunması"],["Şedde","Harfin iki kez okunmasını sağlayan işaret"],["Tenvin","İkişer üstün, esre veya ötre"],["Med","Harfi uzatarak okumak"],["Sure","Kur'an'ın bağımsız bölümlerinden her biri"]],
 tf:[["Kur'an'da 114 sure vardır.",true],["Şedde, harfin iki kez okunmasını sağlar.",true],["Bakara suresi Kur'an'ın en kısa suresidir.",false],["Tenvin, üstün, esre veya ötrenin ikişer olmasıyla oluşur.",true]]};

const KUR68 = {konu:"Kur'an-ı Kerim'i Tanıyorum ve Okuma Kuralları", kaynak:KAY_KUR2,
 p:[["Mushaf ve Kur'an","Kur'an-ı Kerim 114 sure ve 30 cüzden oluşur. Ayet, surenin her bir bölümüdür. Kur'an kitap hâline getirilmiş hâline mushaf denir.","114"],
    ["Okuma adabı ve tertil","Kur'an okurken abdestli ve temiz olmak, Euzü-Besmele ile başlamak, acele etmeden, harflerin hakkını vererek (tertil) okumak güzel adaptır.","Tertil"],
    ["Tecvit ve elif-lam","Tecvit, Kur'an'ı harflerin çıkış yerine (mahrec) ve özelliklerine uygun okuma ilmidir. Elif-lam takısının lamı, güneş harflerinden önce okunmaz (idgam), ay harflerinden önce okunur (izhar).","Tecvit"]],
 q:[["Kur'an-ı Kerim'de kaç sure vardır?",["30","99","114","200"],2],
    ["Kur'an'ı okumaya başlarken ne söylenir?",["Euzü-Besmele","Tekbir","Salavat","Hamdele"],0],
    ["Elif-lam takısının lamı hangi harflerden önce okunmaz?",["Güneş harfleri","Ay harfleri","Med harfleri","Cezm harfleri"],0],
    ["Kur'an'ın en uzun suresi hangisidir?",["Fatiha","İhlas","Kevser","Bakara"],3]],
 m:[["Mushaf","Kitap hâline getirilmiş Kur'an"],["Sure","Kur'an'ın bağımsız bölümü"],["Ayet","Surenin her bir cümlesi veya bölümü"],["Cüz","Kur'an'ın 30 bölümünden her biri"],["Tecvit","Kur'an'ı kurallarına uygun okuma ilmi"],["Tertil","Acele etmeden, harfleri hakkıyla okumak"]],
 tf:[["Kur'an 30 cüzdür.",true],["Bakara suresi kısa bir suredir.",false],["Kur'an'ı abdestli ve temiz ortamda okumaya özen gösterilir.",true],["Ay harflerinden önce elif-lam'ın lamı okunmaz.",false]]};

const KUR9 = {konu:"Kur'an-ı Kerim'i Tanıyorum, Güzel Okuma Kuralları ve Okuyorum", kaynak:KAY_KUR,
 p:[["İlah ve ihlas","İlah, kendisine tapılan varlık demektir; İslam inancında ilah yalnızca Allah'tır. İhlas, ibadet ve davranışlarda yalnızca Allah'ın rızasını gözetmektir. Hz. İbrahim'in İbrahim suresi 40-41. ayetlerdeki duası, namaza devam, soyunun salih olması ve bağışlanma temennisini içerir.","İhlas"],
    ["Harfler ve mahrecler","Mahrec, harfin ağızda çıktığı yerdir. Beş genel mahrec vardır: ağız boşluğu, boğaz, dil, dudaklar ve geniz. Doğru okumak için harfler mahreçlerinden çıkarılır.","Mahrec"],
    ["Med çeşitleri","Tabii med bir elif miktarı uzatılır. Med harfinden sonra aynı kelimede hemze gelirse medd-i muttasıl, sonraki kelimenin başında hemze gelirse medd-i munfasıl oluşur; bunlar tabii medden uzun okunur.","Med"],
    ["Yüzünden okuma","Bu sınıfta Âl-i İmrân suresinin 1-115. ayetleri ve Yâsîn suresinin 1-83. ayetleri yüzünden okunur. Âl-i İmrân 200, Yâsîn 83 ayettir. Âl-i İmrân Medine döneminde, Yâsîn Mekke döneminde inmiştir.","Yâsîn"]],
 q:[["Mahrec ne demektir?",["Harfin çıktığı yer","Ayetin sonu","Surenin adı","Uzatma işareti"],0],
    ["Yâsîn suresi kaç ayettir?",["40","83","114","200"],1],
    ["Âl-i İmrân suresi kaç ayettir?",["120","200","286","114"],1],
    ["İhlas kavramı ne anlama gelir?",["İbadet ve davranışlarda yalnızca Allah'ın rızasını gözetmek","Gösteriş yapmak","İbadeti ertelemek","Kendini beğenmek"],0]],
 m:[["İlah","Kendisine tapılan varlık"],["İhlas","Samimiyetle yalnızca Allah rızası için davranmak"],["Mahrec","Harfin çıkış yeri"],["Med","Harfi uzatarak okumak"],["Hareke","Harfe ses veren işaret"],["Dua","Allah'tan istemek, ona yönelmek"]],
 tf:[["Beş genel mahrec vardır.",true],["Yâsîn suresi Mekke döneminde inmiştir.",true],["Âl-i İmrân suresi 114 ayettir.",false],["Doğru okuma için harfler mahreçlerinden çıkarılmalıdır.",true]]};

const KUR1012 = {konu:"Güzel Okuma Kuralları: Tecvit", kaynak:KAY_KUR2,
 p:[["Nun sakin ve tenvin","Nun sakin veya tenvinden sonra gelen harfe göre dört hüküm vardır. İzhar: boğaz harfleri (hemze, he, ayn, ha, gayn, hı) gelirse açık okunur. İdgam: ye, re, mim, lam, vav, nun gelirse kaynaştırılır. İklab: be gelirse nun mim gibi okunur. İhfa: diğer harflerde genizden gizlenerek okunur.","Nun"],
    ["Mim sakin","Mim sakinden sonra be gelirse ihfa-i şefevî, mim gelirse idgam-ı misleyn, diğer harfler gelirse izhar-ı şefevî uygulanır.","Mim"],
    ["Kalkale","Kalkale harfleri kaf, tı, be, cim ve dal'dır (kutbu ced). Bu harfler sakin olunca çıkış yerinde hafif bir yankı ile okunur.","قطبجد"]],
 q:[["Nun sakin veya tenvinden sonra 'be' gelirse hangi hüküm uygulanır?",["İzhar","İdgam","İklab","İhfa"],2],
    ["Kalkale harfleri hangileridir?",["Kaf, tı, be, cim, dal","Ye, re, mim, lam, vav, nun","Hemze, he, ayn, ha, gayn, hı","Sin, şın, sad, dad, ze"],0],
    ["Boğaz harfleri nun sakin veya tenvinden sonra gelirse hüküm nedir?",["İzhar","İdgam","İklab","İhfa"],0],
    ["Mim sakinden sonra 'be' gelirse hüküm nedir?",["İhfa-i şefevî","İdgam-ı misleyn","İzhar-ı şefevî","İklab"],0]],
 m:[["İzhar","Harfi açık, belirgin okumak"],["İdgam","Harfleri kaynaştırarak okumak"],["İklab","Nun sakin veya tenvinin mim sesine çevrilmesi"],["İhfa","Harfi genizden gizleyerek okumak"],["Kalkale","Sakin harfi hafif yankıyla okumak"],["Tecvit","Kur'an'ı kurallarına uygun okuma ilmi"]],
 tf:[["İklabda nun sakin mim sesine dönüşür.",true],["Kalkale harfleri beş tanedir.",true],["İzhar, harfi gizleyerek okumak demektir.",false],["İdgam, kaynaştırarak okumayı ifade eder.",true]]};

